 77	func TestServeWaitsFromCallbackCompletionAndNeverOverlaps(t *testing.T) {
 78		interval := 40 * time.Millisecond
 79		firstStarted := make(chan struct{})
 80		gate := make(chan struct{})
 81		var gateOnce sync.Once
 82		unblock := func() { gateOnce.Do(func() { close(gate) }) }
 83		completion := make(chan time.Time, 1)
 84		secondStarted := make(chan time.Time, 1)
 85		var calls, active atomic.Int32
 86		ctx, cancel := context.WithCancel(context.Background())
 87		done, joined := launchServe(t, ctx, cancel, unblock, interval, func(got context.Context) error {
 88			if active.Add(1) != 1 {
 89				return errors.New("callbacks overlap")
 90			}
 91			defer active.Add(-1)
 92			n := calls.Add(1)
 93			if n == 1 {
 94				close(firstStarted)
 95				select {
 96				case <-gate:
 97					completion <- time.Now()
 98				case <-got.Done():
 99				}
100				return nil
101			}
102			secondStarted <- time.Now()
103			cancel()
104			return nil
105		}, func() error { return nil })
106		awaitEvent(t, firstStarted, "first refresh")
107		// Deliberately hold the first callback past the interval. A ticker based on
108		// start time would have a ready tick when this callback finally returns.
109		timer := time.NewTimer(2 * interval)
110		defer timer.Stop()
111		select {
112		case <-timer.C:
113		case err := <-done:
114			t.Fatalf("Serve exited while callback was held: %v", err)
115		}
116		unblock()
117		var completed, next time.Time
118		select {
119		case completed = <-completion:
120		case <-time.After(5 * time.Second):
121			t.Fatal("first callback did not complete")
122		}
123		select {
124		case next = <-secondStarted:
125		case <-time.After(5 * time.Second):
126			select {
127			case err := <-done:
128				t.Fatalf("Serve exited before recurrence: %v", err)
129			default:
130				t.Fatal("second refresh did not start")
131			}
132		}
133		if elapsed := next.Sub(completed); elapsed < interval {
134			t.Errorf("delay after completion = %s; want at least %s", elapsed, interval)
135		}
136		awaitEvent(t, joined, "Serve completion")
137		if err := awaitResult(t, done); err != nil {
138			t.Fatal(err)
139		}
140		if calls.Load() != 2 || active.Load() != 0 {
141			t.Fatalf("calls %d, active %d; want two completed callbacks", calls.Load(), active.Load())
142		}
143	}
