147			name := "nil callback result"
148			if callbackErr != nil {
149				name = "callback error"
150			}
151			t.Run(name, func(t *testing.T) {
152				started := make(chan struct{})
153				cleanupStarted := make(chan struct{})
154				gate := make(chan struct{})
155				var gateOnce sync.Once
156				unblock := func() { gateOnce.Do(func() { close(gate) }) }
157				released := make(chan struct{})
