184				case <-time.After(30 * time.Millisecond):
185				}
186				unblock()
187				err := awaitResult(t, done)
188				if callbackErr == nil && err != nil || callbackErr != nil && !errors.Is(err, callbackErr) {
189					t.Fatalf("Serve = %v; want callback result %v", err, callbackErr)
190				}
