199	func TestServeIndependentInvocations(t *testing.T) {
200		starts := []chan struct{}{make(chan struct{}, 8), make(chan struct{}, 8)}
201		cancels := make([]context.CancelFunc, 2)
202		results := make([]<-chan error, 2)
203		var releases [2]atomic.Int32
204		for n := range starts {
205			ctx, cancel := context.WithCancel(context.Background())
206			cancels[n] = cancel
207			results[n], _ = launchServe(t, ctx, cancel, func() {}, 10*time.Millisecond, func(context.Context) error {
208				select {
209				case starts[n] <- struct{}{}:
210				default:
211				}
212				return nil
213			}, func() error { releases[n].Add(1); return nil })
214		}
215		awaitEvent(t, starts[0], "first instance startup")
216		awaitEvent(t, starts[1], "second instance startup")
217		cancels[0]()
218		if err := awaitResult(t, results[0]); err != nil {
219			t.Fatal(err)
220		}
221		// Discard already-buffered starts, then require a later start from the live
222		// instance after the first invocation has returned.
223		for len(starts[1]) > 0 {
224			<-starts[1]
225		}
226		awaitEvent(t, starts[1], "second instance recurrence after first stopped")
227		cancels[1]()
228		if err := awaitResult(t, results[1]); err != nil {
229			t.Fatal(err)
230		}
231		for n := range releases {
