109				}
110			})
111		}
112		t.Run("recurrence and in flight termination", func(t *testing.T) {
113			for _, termination := range []os.Signal{syscall.SIGTERM, os.Interrupt} {
114				t.Run(termination.String(), func(t *testing.T) {
115					requests := make(chan int32, 8)
116					canceled := make(chan struct{})
117					secondResponse := make(chan struct{})
118					var calls atomic.Int32
119					server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
120						n := calls.Add(1)
121						requests <- n
122						if n == 2 {
123							select {
124							case <-secondResponse:
125							case <-r.Context().Done():
126								return
127							}
128						}
129						if n >= 3 {
130							<-r.Context().Done()
131							if n == 3 {
132								close(canceled)
133							}
134							return
135						}
136						fmt.Fprintf(w, "[{\"key\":\"alpha\",\"text\":\"cycle %d\"}]", n)
137					}))
138					t.Cleanup(server.Close)
139					path := filepath.Join(t.TempDir(), "records.json")
140					ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
141					cmd := exec.CommandContext(ctx, binary, "watch", "--url", server.URL, "--file", path, "--interval", "150ms")
142					cmd.Env = childEnvironment()
143					cmd.WaitDelay = time.Second
144					var stdout, stderr bytes.Buffer
145					cmd.Stdout, cmd.Stderr = &stdout, &stderr
146					if err := cmd.Start(); err != nil {
147						cancel()
148						t.Fatal(err)
149					}
150					done := make(chan error, 1)
151					joined := make(chan struct{})
152					t.Cleanup(func() {
153						cancel()
154						select {
155						case <-joined:
156						case <-time.After(5 * time.Second):
157							t.Error("watch process did not join during cleanup")
158						}
159					})
160					go func() { done <- cmd.Wait(); close(joined) }()
161					for n := int32(1); n <= 2; n++ {
162						select {
163						case got := <-requests:
164							if got != n {
165								t.Fatalf("request sequence = %d; want %d", got, n)
166							}
167						case <-joined:
168							t.Fatalf("watch exited before refresh %d", n)
169						case <-time.After(5 * time.Second):
170							t.Fatalf("refresh %d did not start", n)
171						}
172						waitForContents(t, path, fmt.Sprintf("[{\"key\":\"alpha\",\"text\":\"cycle %d\"}]\n", n), joined)
173						if n == 1 {
174							close(secondResponse)
175						}
176					}
177					select {
178					case n := <-requests:
179						if n != 3 {
180							t.Fatalf("third request = %d", n)
181						}
182					case <-time.After(5 * time.Second):
183						t.Fatal("third request did not start")
184					}
185					if err := cmd.Process.Signal(termination); err != nil {
186						t.Fatal(err)
187					}
188					select {
189					case err := <-done:
190						if err != nil {
191							t.Fatalf("terminated watch = %v, stderr %q", err, stderr.String())
192						}
193					case <-time.After(5 * time.Second):
194						t.Fatal("terminated watch did not join")
195					}
196					select {
197					case <-canceled:
198					case <-time.After(5 * time.Second):
199						t.Fatal("in-flight HTTP request was not canceled")
200					}
201					if stdout.Len() != 0 || stderr.Len() != 0 {
202						t.Fatalf("successful watch stdout %q, stderr %q; want empty", stdout.String(), stderr.String())
203					}
204					assertContents(t, path, "[{\"key\":\"alpha\",\"text\":\"cycle 2\"}]\n")
205					if calls.Load() != 3 {
206						t.Fatalf("requests after shutdown = %d; want 3", calls.Load())
207					}
208				})
209			}
210		})
211	}
