237	func assertProcess(t *testing.T, binary string, args []string, input string, wantCode int) {
238		t.Helper()
239		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
240		defer cancel()
241		cmd := exec.CommandContext(ctx, binary, args...)
242		cmd.Env = childEnvironment()
243		cmd.WaitDelay = time.Second
244		cmd.Stdin = strings.NewReader(input)
245		var stdout, stderr bytes.Buffer
246		cmd.Stdout, cmd.Stderr = &stdout, &stderr
247		err := cmd.Run()
248		if ctx.Err() != nil {
249			t.Fatalf("command timed out: %v", ctx.Err())
250		}
251		code := 0
252		if err != nil {
253			exit, ok := err.(*exec.ExitError)
254			if !ok {
255				t.Fatal(err)
256			}
257			code = exit.ExitCode()
258		}
259		if code != wantCode || stdout.Len() != 0 || wantCode == 0 && stderr.Len() != 0 || wantCode != 0 && stderr.Len() == 0 {
260			t.Fatalf("%v: status %d, stdout %q, stderr %q; want status %d and matching streams", args, code, stdout.String(), stderr.String(), wantCode)
