272	func waitForContents(t *testing.T, path, want string, joined <-chan struct{}) {
273		t.Helper()
274		timer := time.NewTimer(5 * time.Second)
275		defer timer.Stop()
276		ticker := time.NewTicker(5 * time.Millisecond)
277		defer ticker.Stop()
278		for {
279			got, err := os.ReadFile(path)
280			if err == nil && string(got) == want {
281				return
282			}
283			select {
284			case <-timer.C:
285				t.Fatalf("publication = %q, %v; want %q", got, err, want)
286			case <-joined:
287				t.Fatal("watch exited before publication")
288			case <-ticker.C:
289			}
290		}
291	}

