 3	import (
 4		"encoding/csv"
 5		"errors"
 6		"fmt"
 7		"io"
 8		"os"
 9		"path/filepath"
10		"regexp"
11		"strings"
12	)
13	
14	// ErrInvalidRecord identifies a rejected key or import/refresh record.
15	var ErrInvalidRecord = errors.New("invalid record")
16	
17	// ErrNotImplemented is retained for compatibility with existing consumers.
18	var ErrNotImplemented = errors.New("operation not implemented")
19	var keyPattern = regexp.MustCompile(`^[a-z]+$`)
20	
21	type Index struct{ root string }
22	
23	// Open returns an index rooted at root. It does not access the filesystem.
24	func Open(root string) *Index { return &Index{root: root} }
25	
26	// Put atomically replaces key's text. Text may be empty or whitespace.
27	func (i *Index) Put(key, text string) error {
28		if !keyPattern.MatchString(key) {
29			return ErrInvalidRecord
30		}
31		if err := os.MkdirAll(i.root, 0700); err != nil {
32			return err
33		}
34		return replaceFile(filepath.Join(i.root, key), []byte(text))
35	}
36	
37	// Get returns the exact text stored for key.
38	func (i *Index) Get(key string) (string, error) {
39		if !keyPattern.MatchString(key) {
40			return "", ErrInvalidRecord
41		}
42		b, err := os.ReadFile(filepath.Join(i.root, key))
43		return string(b), err
44	}
45	
46	// ApplyCSV applies two-field key/text records in order. On failure, earlier
47	// accepted rows remain stored and no later rows are applied.
48	func (i *Index) ApplyCSV(r io.Reader) error {
49		reader := csv.NewReader(r)
50		reader.FieldsPerRecord = 2
51		for row := 1; ; row++ {
52			fields, err := reader.Read()
53			if errors.Is(err, io.EOF) {
54				return nil
55			}
56			if err != nil {
57				if errors.Is(err, csv.ErrFieldCount) {
58					err = errors.Join(ErrInvalidRecord, err)
59				}
60				return fmt.Errorf("CSV row %d: %w", row, err)
61			}
62			if err := validateRecord(Record{Key: fields[0], Text: fields[1]}); err != nil {
63				return fmt.Errorf("CSV row %d: %w", row, err)
64			}
65			if err := i.Put(fields[0], fields[1]); err != nil {
66				return fmt.Errorf("CSV row %d: %w", row, err)
67			}
68		}
69	}
70	
71	func validateRecord(record Record) error {
72		if !keyPattern.MatchString(record.Key) || strings.TrimSpace(record.Text) == "" {
73			return ErrInvalidRecord
74		}
75		return nil
76	}
77	
78	// replaceFile stages data beside the destination so rename publishes a complete
79	// snapshot. Failure before rename leaves the destination untouched.
80	func replaceFile(path string, data []byte) error {
81		f, err := os.CreateTemp(filepath.Dir(path), ".record-*")
82		if err != nil {
83			return err
84		}
85		defer os.Remove(f.Name())
86		if _, err := f.Write(data); err != nil {
87			f.Close()
88			return err
89		}
90		if err := f.Close(); err != nil {
91			return err
92		}
93		return os.Rename(f.Name(), path)
94	}

