 3	import (
 4		"context"
 5		"encoding/json"
 6		"errors"
 7		"fmt"
 8		"io"
 9		"net/http"
10	)
11	
12	// Record is the key/text representation used by refresh responses.
13	type Record struct {
14		Key  string `json:"key"`
15		Text string `json:"text"`
16	}
17	
18	// Refresh fetches and validates one JSON array, then atomically publishes its
19	// compact representation plus a newline. The supplied client remains borrowed.
20	func Refresh(ctx context.Context, client *http.Client, endpoint, path string) error {
21		request, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
22		if err != nil {
23			return fmt.Errorf("create refresh request: %w", err)
24		}
25		// A redirect would issue another GET and could hide a rejected status. Copy
26		// the borrowed client's configuration without changing its redirect policy.
27		requestClient := *client
28		requestClient.CheckRedirect = func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }
29		response, err := requestClient.Do(request)
30		if err != nil {
31			return fmt.Errorf("fetch records: %w", err)
32		}
33		defer response.Body.Close()
34		if response.StatusCode != http.StatusOK {
35			return fmt.Errorf("fetch records: HTTP status %d", response.StatusCode)
36		}
37		decoder := json.NewDecoder(response.Body)
38		var records []Record
39		if err := decoder.Decode(&records); err != nil {
40			return fmt.Errorf("decode records: %w", err)
41		}
42		if records == nil {
43			return fmt.Errorf("expected a JSON array: %w", ErrInvalidRecord)
44		}
45		var extra any
46		if err := decoder.Decode(&extra); !errors.Is(err, io.EOF) {
47			if err == nil {
48				return errors.New("unexpected data after records")
49			}
50			return fmt.Errorf("read after records: %w", err)
51		}
52		for n, record := range records {
53			if err := validateRecord(record); err != nil {
54				return fmt.Errorf("record %d: %w", n+1, err)
55			}
56		}
57		data, err := json.Marshal(records)
58		if err != nil {
59			return fmt.Errorf("encode records: %w", err)
60		}
61		if err := replaceFile(path, append(data, '\n')); err != nil {
62			return fmt.Errorf("publish records: %w", err)
63		}
64		return nil
65	}

