 3	import (
 4		"context"
 5		"errors"
 6		"time"
 7	)
 8	
 9	var ErrInvalidInterval = errors.New("invalid interval")
10	
11	// Serve runs refresh sequentially, waiting interval after each successful call.
12	// For a valid interval, release runs exactly once after all callback work ends.
13	// Cancellation alone succeeds; callback errors, including those returned during
14	// cancellation, and release errors retain their identities.
15	func Serve(ctx context.Context, interval time.Duration, refresh func(context.Context) error, release func() error) (err error) {
16		if interval <= 0 {
17			return ErrInvalidInterval
18		}
19		defer func() { err = errors.Join(err, release()) }()
20		for {
21			if ctx.Err() != nil {
22				return nil
23			}
24			if err := refresh(ctx); err != nil {
25				return err
26			}
27			timer := time.NewTimer(interval)
28			select {
29			case <-ctx.Done():
30				timer.Stop()
31				return nil
32			case <-timer.C:
33			}
34		}
35	}

