17	
18	func run(args []string) error {
19		return runContext(context.Background(), args, os.Stdin)
20	}
21	
22	func runContext(ctx context.Context, args []string, input io.Reader) error {
23		if len(args) == 0 {
24			return fmt.Errorf("usage: indexer put DIR KEY TEXT | apply --dir DIR | watch --url URL --file PATH --interval DURATION")
25		}
26		switch args[0] {
27		case "put":
28			// Preserve positional arguments verbatim, including a text beginning '-'.
29			if len(args) != 4 {
30				return fmt.Errorf("usage: indexer put DIR KEY TEXT")
31			}
32			return indexer.Open(args[1]).Put(args[2], args[3])
33		case "apply":
34			flags := flag.NewFlagSet("apply", flag.ContinueOnError)
35			flags.SetOutput(io.Discard)
36			dir := flags.String("dir", "", "index directory")
37			if err := flags.Parse(args[1:]); err != nil {
38				return err
39			}
40			if *dir == "" || flags.NArg() != 0 {
41				return fmt.Errorf("usage: indexer apply --dir DIR")
42			}
43			return indexer.Open(*dir).ApplyCSV(input)
44		case "watch":
45			return runWatch(ctx, args[1:])
46		default:
47			return fmt.Errorf("unknown command %q", args[0])
48		}
49	}
50	
51	func runWatch(ctx context.Context, args []string) error {
52		flags := flag.NewFlagSet("watch", flag.ContinueOnError)
53		flags.SetOutput(io.Discard)
54		endpoint := flags.String("url", "", "records URL")
55		path := flags.String("file", "", "destination file")
56		interval := flags.Duration("interval", 0, "delay between refreshes")
57		if err := flags.Parse(args); err != nil {
58			return err
59		}
60		parsed, err := url.Parse(*endpoint)
61		if err != nil || parsed.Hostname() == "" || (parsed.Scheme != "http" && parsed.Scheme != "https") || *path == "" || *interval <= 0 || flags.NArg() != 0 {
62			return fmt.Errorf("usage: indexer watch --url HTTP_URL --file PATH --interval POSITIVE_DURATION")
63		}
64		transport := http.DefaultTransport.(*http.Transport).Clone()
65		client := &http.Client{Transport: transport}
66		return indexer.Serve(ctx, *interval, func(ctx context.Context) error {
67			err := indexer.Refresh(ctx, client, *endpoint, *path)
68			if ctx.Err() != nil && errors.Is(err, ctx.Err()) {
69				return nil
70			}
71			return err
72		}, func() error {
73			client.CloseIdleConnections()
74			return nil
75		})
76	}
77	
78	func main() {
79		ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
80		defer stop()
81		if err := runContext(ctx, os.Args[1:], os.Stdin); err != nil {
82			fmt.Fprintln(os.Stderr, err)
83			os.Exit(2)
84		}
85	}
